from pathlib import Path
from datetime import datetime
import re
import sys

root = Path.cwd()

if not (root / "package.json").exists():
    print("ERRO: execute este arquivo na raiz do projeto site-ludo, onde está o package.json.")
    sys.exit(1)

eventos_dir = root / "src" / "app" / "eventos"
page_file = eventos_dir / "page.tsx"
css_file = eventos_dir / "eventos.css"

if not page_file.exists() or not css_file.exists():
    print("ERRO: não encontrei src/app/eventos/page.tsx ou eventos.css.")
    sys.exit(1)

stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
backup_dir = root / "backups" / f"home-eventos-v3-{stamp}"
backup_dir.mkdir(parents=True, exist_ok=True)

(backup_dir / "page.tsx").write_text(page_file.read_text(encoding="utf-8"), encoding="utf-8")
(backup_dir / "eventos.css").write_text(css_file.read_text(encoding="utf-8"), encoding="utf-8")

page = '\nimport type { CSSProperties } from "react";\nimport Link from "next/link";\nimport { eventos } from "./data";\n\nexport const metadata = {\n  title: "LUDO Eventos",\n  description:\n    "Fotografia, vídeo e experiências digitais para eventos.",\n};\n\nconst heroBanners = [\n  "/eventos/imagens/portal-hero.svg",\n  "/eventos/imagens/momento-01.svg",\n  "/eventos/imagens/momento-02.svg",\n  "/eventos/imagens/momento-03.svg",\n  "/eventos/imagens/momento-04.svg",\n  "/eventos/imagens/momento-05.svg",\n];\n\nexport default function EventosPage() {\n  return (\n    <main className="ludo-event-page ludo-portal ludo-portal-v3">\n      <section className="ludo-portal-hero ludo-portal-hero-v3">\n        <div className="ludo-hero-slides" aria-hidden="true">\n          {heroBanners.map((banner, index) => (\n            <img\n              key={banner}\n              src={banner}\n              alt=""\n              className="ludo-hero-slide"\n              style={\n                {\n                  "--slide-delay": `${index * 6}s`,\n                } as CSSProperties\n              }\n            />\n          ))}\n        </div>\n\n        <div className="ludo-hero-overlay" />\n        <div className="ludo-grid" />\n        <div className="ludo-stars ludo-stars-one" aria-hidden="true" />\n        <div className="ludo-stars ludo-stars-two" aria-hidden="true" />\n\n        <div className="ludo-container">\n          <nav className="ludo-event-nav">\n            <Link href="/" className="ludo-event-logo ludo-logo-special">\n              <span className="ludo-favicon-wrap">\n                <img src="/icon.png" alt="Logo LUDO" />\n              </span>\n\n              <div>\n                <strong>LUDO</strong>\n                <small>EVENTOS</small>\n              </div>\n            </Link>\n\n            <Link href="/" className="ludo-nav-button">\n              Voltar à LUDO\n            </Link>\n          </nav>\n\n          <div className="ludo-portal-content ludo-portal-content-v3">\n            <p className="ludo-eyebrow">\n              FOTOGRAFIA • VÍDEO • EXPERIÊNCIAS\n            </p>\n\n            <h1 className="ludo-event-display">\n              <span className="ludo-hero-word ludo-viva">Viva.</span>\n              <span className="ludo-hero-word ludo-reviva">Reviva.</span>\n            </h1>\n\n            <p className="ludo-description">\n              Eventos que ganham movimento, som, luz e uma entrega\n              digital à altura de cada memória.\n            </p>\n\n            <div className="ludo-actions">\n              <a href="#experiencias" className="ludo-button primary">\n                Explorar experiências\n              </a>\n\n              <a href="#acesso" className="ludo-button">\n                Acessar meu evento\n              </a>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <section\n        className="ludo-section ludo-experiences-zone"\n        id="experiencias"\n      >\n        <div className="ludo-stars ludo-stars-three" aria-hidden="true" />\n        <div className="ludo-stars ludo-stars-four" aria-hidden="true" />\n\n        <div className="ludo-orb-field" aria-hidden="true">\n          <i className="ludo-orb orb-a" />\n          <i className="ludo-orb orb-b" />\n          <i className="ludo-orb orb-c" />\n          <i className="ludo-orb orb-d" />\n        </div>\n\n        <div className="ludo-container ludo-experiences-content">\n          <p className="ludo-eyebrow">PORTAIS POR EXPERIÊNCIA</p>\n\n          <h2 className="ludo-section-title">\n            Cada evento com uma\n            <span> personalidade própria.</span>\n          </h2>\n\n          <p className="ludo-experiences-intro">\n            Escolha uma experiência. Cada portal possui atmosfera,\n            recursos e identidade visual pensados para o tipo de evento.\n          </p>\n\n          <div className="ludo-portal-grid ludo-portal-grid-v3">\n            {eventos.map((evento) => (\n              <Link\n                href={`/eventos/${evento.slug}/`}\n                key={evento.slug}\n                className="ludo-portal-card ludo-portal-card-v3"\n                style={\n                  {\n                    "--card-color": evento.cor,\n                    "--card-color-2": evento.corSecundaria,\n                  } as CSSProperties\n                }\n              >\n                <div className="ludo-card-ambient" />\n\n                <div className="ludo-card-top">\n                  <small>{evento.numero} / EXPERIÊNCIA</small>\n                  <b aria-hidden="true">↗</b>\n                </div>\n\n                <div className="ludo-card-content">\n                  <small>{evento.etiqueta}</small>\n                  <h3>{evento.titulo}</h3>\n                  <p>{evento.descricao}</p>\n                  <strong>\n                    Explorar experiência\n                    <span aria-hidden="true">→</span>\n                  </strong>\n                </div>\n              </Link>\n            ))}\n          </div>\n        </div>\n      </section>\n\n      <section className="ludo-section" id="acesso">\n        <div className="ludo-container">\n          <div className="ludo-access-panel">\n            <p className="ludo-eyebrow">ÁREA DO CLIENTE</p>\n\n            <h2 className="ludo-section-title">\n              Encontre suas <span>memórias.</span>\n            </h2>\n\n            <p className="ludo-description">\n              A área de acesso será conectada à galeria privada\n              correspondente a cada evento.\n            </p>\n          </div>\n        </div>\n      </section>\n    </main>\n  );\n}\n'
css_patch = '\n/* LUDO PORTAL HOME V3 START */\n\n.ludo-portal-v3 {\n  position: relative;\n  background: #05050a;\n}\n\n.ludo-portal-hero-v3 {\n  min-height: 100svh;\n  overflow: hidden;\n  background: #05050a;\n}\n\n.ludo-hero-slides,\n.ludo-hero-overlay {\n  position: absolute;\n  inset: 0;\n}\n\n.ludo-hero-slides {\n  z-index: -5;\n  overflow: hidden;\n  background: #05050a;\n}\n\n.ludo-hero-slide {\n  position: absolute;\n  inset: -3%;\n  width: 106%;\n  height: 106%;\n  object-fit: cover;\n  opacity: 0;\n  filter: saturate(.92) contrast(1.08) brightness(.52);\n  transform: scale(1.06);\n  animation: ludoHeroFade 36s infinite;\n  animation-delay: var(--slide-delay);\n  will-change: opacity, transform;\n}\n\n.ludo-hero-overlay {\n  z-index: -3;\n  background:\n    linear-gradient(\n      90deg,\n      rgba(4, 3, 10, .97) 0%,\n      rgba(4, 3, 10, .83) 42%,\n      rgba(4, 3, 10, .34) 74%,\n      rgba(4, 3, 10, .56) 100%\n    ),\n    linear-gradient(\n      0deg,\n      #05050a 0%,\n      transparent 42%,\n      rgba(2, 2, 8, .58) 100%\n    );\n}\n\n@keyframes ludoHeroFade {\n  0% {\n    opacity: 0;\n    transform: scale(1.08);\n  }\n\n  4%,\n  16% {\n    opacity: 1;\n  }\n\n  21%,\n  100% {\n    opacity: 0;\n    transform: scale(1.01);\n  }\n}\n\n.ludo-logo-special {\n  position: relative;\n  z-index: 2;\n}\n\n.ludo-favicon-wrap {\n  position: relative;\n  display: grid;\n  width: 52px;\n  height: 52px;\n  place-items: center;\n  border-radius: 17px;\n  isolation: isolate;\n  animation: ludoLogoFloat 4.5s ease-in-out infinite;\n}\n\n.ludo-favicon-wrap::before {\n  content: "";\n  position: absolute;\n  inset: -4px;\n  z-index: -2;\n  border-radius: 21px;\n  background:\n    conic-gradient(\n      from 0deg,\n      #49e7ff,\n      #496fff,\n      #b758ff,\n      #49e7ff\n    );\n  animation: ludoLogoSpin 6s linear infinite;\n}\n\n.ludo-favicon-wrap::after {\n  content: "";\n  position: absolute;\n  inset: 2px;\n  z-index: -1;\n  border-radius: 15px;\n  background: rgba(5, 5, 10, .94);\n  box-shadow:\n    0 0 28px rgba(76, 160, 255, .42),\n    0 0 58px rgba(164, 78, 255, .24);\n}\n\n.ludo-favicon-wrap img {\n  width: 42px;\n  height: 42px;\n  object-fit: contain;\n  filter: drop-shadow(0 0 12px rgba(74, 201, 255, .48));\n}\n\n@keyframes ludoLogoSpin {\n  to {\n    transform: rotate(360deg);\n  }\n}\n\n@keyframes ludoLogoFloat {\n  0%,\n  100% {\n    transform: translateY(0) rotate(-1deg);\n  }\n\n  50% {\n    transform: translateY(-5px) rotate(1deg);\n  }\n}\n\n.ludo-portal-content-v3 {\n  position: relative;\n  z-index: 4;\n  padding-top: clamp(125px, 16vh, 190px);\n  padding-bottom: 100px;\n}\n\n.ludo-event-display {\n  display: inline-flex;\n  flex-direction: column;\n  margin: 30px 0 20px;\n  font-family:\n    Impact,\n    Haettenschweiler,\n    "Arial Narrow Bold",\n    "Helvetica Neue",\n    sans-serif;\n  font-size: clamp(5.4rem, 14vw, 12.5rem);\n  font-weight: 400;\n  line-height: .69;\n  letter-spacing: -.045em;\n  text-transform: uppercase;\n  cursor: default;\n}\n\n.ludo-hero-word {\n  position: relative;\n  display: block;\n  color: transparent;\n  background:\n    linear-gradient(\n      110deg,\n      #ffffff 0%,\n      #ffffff 38%,\n      #bff8ff 47%,\n      #ffffff 53%,\n      #ffffff 100%\n    );\n  background-size: 250% 100%;\n  background-position: 100% 0;\n  background-clip: text;\n  -webkit-background-clip: text;\n  transition:\n    text-shadow .45s ease,\n    filter .45s ease,\n    transform .45s ease;\n}\n\n.ludo-reviva {\n  background-image:\n    linear-gradient(\n      110deg,\n      #47e6ff 0%,\n      #5c8bff 35%,\n      #d1fbff 49%,\n      #a75dff 64%,\n      #47e6ff 100%\n    );\n}\n\n.ludo-event-display:hover .ludo-hero-word {\n  animation: ludoTextShine 1.2s ease both;\n  filter: brightness(1.12);\n  text-shadow:\n    0 0 12px rgba(255, 255, 255, .26),\n    0 0 28px rgba(83, 196, 255, .32),\n    0 0 58px rgba(149, 84, 255, .2);\n}\n\n.ludo-event-display:hover .ludo-viva {\n  transform: translateX(8px);\n}\n\n.ludo-event-display:hover .ludo-reviva {\n  transform: translateX(-8px);\n  animation-delay: .08s;\n}\n\n@keyframes ludoTextShine {\n  from {\n    background-position: 100% 0;\n  }\n\n  to {\n    background-position: -100% 0;\n  }\n}\n\n.ludo-stars {\n  position: absolute;\n  inset: 0;\n  pointer-events: none;\n  overflow: hidden;\n}\n\n.ludo-stars::before,\n.ludo-stars::after {\n  content: "";\n  position: absolute;\n  inset: -120px;\n  background-repeat: repeat;\n  will-change: transform;\n}\n\n.ludo-stars-one::before,\n.ludo-stars-three::before {\n  opacity: .42;\n  background-image:\n    radial-gradient(circle, rgba(255, 255, 255, .95) 0 1px, transparent 1.5px),\n    radial-gradient(circle, rgba(104, 214, 255, .7) 0 1px, transparent 1.7px);\n  background-size: 125px 125px, 195px 195px;\n  background-position: 12px 18px, 56px 83px;\n  animation: ludoStarDrift 64s linear infinite;\n}\n\n.ludo-stars-two::after,\n.ludo-stars-four::after {\n  opacity: .27;\n  background-image:\n    radial-gradient(circle, rgba(255, 255, 255, .9) 0 1.4px, transparent 2px),\n    radial-gradient(circle, rgba(181, 104, 255, .75) 0 1px, transparent 1.8px);\n  background-size: 280px 280px, 360px 360px;\n  background-position: 24px 42px, 140px 110px;\n  animation: ludoStarDriftReverse 92s linear infinite;\n}\n\n@keyframes ludoStarDrift {\n  to {\n    transform: translate3d(0, -260px, 0);\n  }\n}\n\n@keyframes ludoStarDriftReverse {\n  to {\n    transform: translate3d(130px, -220px, 0);\n  }\n}\n\n.ludo-experiences-zone {\n  min-height: 100vh;\n  isolation: isolate;\n  overflow: hidden;\n  background:\n    linear-gradient(\n      180deg,\n      #05050a 0%,\n      #080612 52%,\n      #05050a 100%\n    );\n}\n\n.ludo-experiences-content {\n  position: relative;\n  z-index: 4;\n}\n\n.ludo-experiences-intro {\n  max-width: 700px;\n  margin-top: 26px;\n  color: rgba(255, 255, 255, .5);\n  font-size: 1.05rem;\n  line-height: 1.75;\n}\n\n.ludo-orb-field {\n  position: absolute;\n  inset: 0;\n  z-index: -1;\n  overflow: hidden;\n  pointer-events: none;\n}\n\n.ludo-orb {\n  position: absolute;\n  display: block;\n  border-radius: 50%;\n  filter: blur(85px);\n  opacity: .25;\n  will-change: transform;\n}\n\n.orb-a {\n  top: 4%;\n  left: -8%;\n  width: 360px;\n  height: 360px;\n  background: #654cff;\n  animation: ludoOrbA 18s ease-in-out infinite alternate;\n}\n\n.orb-b {\n  top: 22%;\n  right: -10%;\n  width: 430px;\n  height: 430px;\n  background: #24d5ff;\n  animation: ludoOrbB 22s ease-in-out infinite alternate;\n}\n\n.orb-c {\n  bottom: 0;\n  left: 28%;\n  width: 410px;\n  height: 410px;\n  background: #e32bbd;\n  animation: ludoOrbC 25s ease-in-out infinite alternate;\n}\n\n.orb-d {\n  top: 42%;\n  left: 48%;\n  width: 300px;\n  height: 300px;\n  background: #7eeb64;\n  opacity: .16;\n  animation: ludoOrbD 20s ease-in-out infinite alternate;\n}\n\n@keyframes ludoOrbA {\n  to {\n    transform: translate3d(160px, 150px, 0) scale(1.18);\n  }\n}\n\n@keyframes ludoOrbB {\n  to {\n    transform: translate3d(-190px, 100px, 0) scale(.86);\n  }\n}\n\n@keyframes ludoOrbC {\n  to {\n    transform: translate3d(220px, -170px, 0) scale(1.14);\n  }\n}\n\n@keyframes ludoOrbD {\n  to {\n    transform: translate3d(-180px, 160px, 0) scale(1.24);\n  }\n}\n\n.ludo-portal-grid-v3 {\n  position: relative;\n  z-index: 4;\n}\n\n.ludo-portal-card-v3 {\n  isolation: isolate;\n  box-shadow:\n    0 26px 65px rgba(0, 0, 0, .26),\n    inset 0 1px 0 rgba(255, 255, 255, .06);\n  transform-style: preserve-3d;\n  transition:\n    transform .5s cubic-bezier(.2, .8, .2, 1),\n    border-color .4s ease,\n    box-shadow .5s ease;\n}\n\n.ludo-portal-card-v3::before {\n  content: "";\n  position: absolute;\n  inset: -55%;\n  z-index: 2;\n  opacity: 0;\n  background:\n    linear-gradient(\n      115deg,\n      transparent 40%,\n      rgba(255, 255, 255, .3) 49%,\n      transparent 58%\n    );\n  transform: translateX(-40%) rotate(10deg);\n  transition:\n    opacity .3s ease,\n    transform .8s ease;\n  pointer-events: none;\n}\n\n.ludo-portal-card-v3:hover {\n  transform:\n    perspective(1200px)\n    translateY(-13px)\n    rotateX(1.5deg)\n    rotateY(-1.5deg)\n    scale(1.015);\n  border-color: rgba(255, 255, 255, .34);\n  box-shadow:\n    0 34px 90px rgba(0, 0, 0, .42),\n    0 0 38px color-mix(in srgb, var(--card-color) 28%, transparent);\n}\n\n.ludo-portal-card-v3:hover::before {\n  opacity: 1;\n  transform: translateX(42%) rotate(10deg);\n}\n\n.ludo-card-ambient {\n  position: absolute;\n  inset: 0;\n  z-index: 1;\n  background:\n    radial-gradient(\n      circle at 25% 30%,\n      color-mix(in srgb, var(--card-color) 52%, transparent),\n      transparent 38%\n    ),\n    radial-gradient(\n      circle at 78% 22%,\n      color-mix(in srgb, var(--card-color-2) 46%, transparent),\n      transparent 34%\n    );\n  filter: saturate(1.15);\n  transition:\n    transform .9s ease,\n    filter .6s ease;\n}\n\n.ludo-portal-card-v3:hover .ludo-card-ambient {\n  transform: scale(1.15) rotate(2deg);\n  filter: saturate(1.42) brightness(1.08);\n}\n\n.ludo-portal-card-v3 .ludo-card-top,\n.ludo-portal-card-v3 .ludo-card-content {\n  z-index: 5;\n}\n\n.ludo-portal-card-v3 .ludo-card-top b {\n  transition:\n    transform .45s ease,\n    color .35s ease,\n    background .35s ease,\n    box-shadow .35s ease;\n}\n\n.ludo-portal-card-v3:hover .ludo-card-top b {\n  color: #05050a;\n  background: #fff;\n  transform: rotate(45deg) scale(1.06);\n  box-shadow: 0 0 26px rgba(255, 255, 255, .35);\n}\n\n.ludo-portal-card-v3 .ludo-card-content h3,\n.ludo-portal-card-v3 .ludo-card-content p,\n.ludo-portal-card-v3 .ludo-card-content strong {\n  transition:\n    transform .45s ease,\n    color .35s ease;\n}\n\n.ludo-portal-card-v3:hover .ludo-card-content h3 {\n  transform: translateY(-7px);\n}\n\n.ludo-portal-card-v3:hover .ludo-card-content p {\n  color: rgba(255, 255, 255, .72);\n  transform: translateY(-5px);\n}\n\n.ludo-portal-card-v3 .ludo-card-content strong {\n  display: flex;\n  align-items: center;\n  gap: 9px;\n}\n\n.ludo-portal-card-v3:hover .ludo-card-content strong {\n  color: var(--card-color-2);\n  transform: translateX(6px);\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .ludo-hero-slide,\n  .ludo-favicon-wrap,\n  .ludo-favicon-wrap::before,\n  .ludo-stars::before,\n  .ludo-stars::after,\n  .ludo-orb {\n    animation: none !important;\n  }\n\n  .ludo-hero-slide:first-child {\n    opacity: 1;\n  }\n}\n\n@media (max-width: 700px) {\n  .ludo-event-display {\n    font-size: clamp(4.6rem, 23vw, 7rem);\n  }\n\n  .ludo-event-display:hover .ludo-viva,\n  .ludo-event-display:hover .ludo-reviva {\n    transform: none;\n  }\n\n  .ludo-favicon-wrap {\n    width: 47px;\n    height: 47px;\n  }\n\n  .ludo-favicon-wrap img {\n    width: 38px;\n    height: 38px;\n  }\n\n  .ludo-experiences-zone {\n    padding-top: 85px;\n  }\n}\n\n/* LUDO PORTAL HOME V3 END */\n'

page_file.write_text(page.strip() + "\n", encoding="utf-8")

current_css = css_file.read_text(encoding="utf-8")
pattern = re.compile(
    r"/\* LUDO PORTAL HOME V3 START \*/.*?/\* LUDO PORTAL HOME V3 END \*/",
    re.DOTALL,
)

if pattern.search(current_css):
    updated_css = pattern.sub(css_patch.strip(), current_css)
else:
    updated_css = current_css.rstrip() + "\n\n" + css_patch.strip() + "\n"

css_file.write_text(updated_css, encoding="utf-8")

print("ATUALIZAÇÃO CONCLUÍDA.")
print(f"Backup criado em: {backup_dir}")
print("Arquivos atualizados:")
print("  src/app/eventos/page.tsx")
print("  src/app/eventos/eventos.css")
print("")
print("Agora execute:")
print("  rm -rf .next")
print("  npm run build")
